#!/usr/bin/env bash
# Differential test: the JS model of migration 076 (used by the fast tests of the routes and of the Flow node) against the REAL SQL.
# It records the scenario and the model's answers (vitest), then replays the same calls on a throwaway PostgreSQL (--network none, destroyed on exit)
# with migrations 001..076 and fails on the first answer that differs (ids generated by the database are compared by shape, everything else exactly).
# Never touches a real database. Needs Docker, the image supabase/postgres:17.6.1.136 locally, node_modules and python3.
set -uo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"; ROOT="${REPO_ROOT:-$(cd "$HERE/../../../.." && pwd)}"; BOOT="$HERE/../../flows-safe-save/bootstrap.sql"
MIGDIR="${MIG076_DIR:-$ROOT/supabase/migrations}"; IMAGE="${ENSAYO_PG_IMAGE:-supabase/postgres:17.6.1.136}"; NAME="diff076-$$-$RANDOM"; W="$(mktemp -d)"
cleanup() { rm -rf "$W"; docker rm -f "$NAME" >/dev/null 2>&1 || true; }; trap cleanup EXIT
( cd "$ROOT" && DIFF_OUT="$W/scenario.json" npx vitest run src/lib/flows/test-support/audio-selection-model.differential.test.ts >"$W/vitest.log" 2>&1 ) || { echo "ABORT: the model scenario failed"; tail -15 "$W/vitest.log"; exit 2; }
[ -s "$W/scenario.json" ] || { echo "ABORT: no scenario recorded"; exit 2; }
docker run -d --name "$NAME" --network none --label wacrm.ensayo=076-selftest --pull never -e POSTGRES_PASSWORD=t "$IMAGE" >/dev/null || { echo "ABORT: container"; exit 2; }
psql_() { docker exec -i -e PGOPTIONS="-c client_min_messages=warning" "$NAME" psql -U supabase_admin -h /var/run/postgresql -d postgres -X -q -A -t -v ON_ERROR_STOP=1 "$@"; }
ok=0; for _ in $(seq 1 120); do sleep 1; l="$(docker logs "$NAME" 2>&1)"; grep -q 'init process complete' <<<"$l" && [ "$(grep -c 'ready to accept' <<<"$l")" -ge 2 ] && psql_ -c 'select 1' >/dev/null 2>&1 && { ok=1; break; }; done
[ "$ok" = 1 ] || { echo "ABORT: database did not start"; exit 2; }
psql_ < "$BOOT" >/dev/null || exit 2
for f in "$MIGDIR"/*.sql; do n="$(basename "$f" | cut -c1-3)"; [ "$n" -le 76 ] && { psql_ < "$f" >/dev/null 2>"$W/m.err" || { echo "ABORT migration $f"; head -2 "$W/m.err"; exit 2; }; }; done
python3 - "$W/scenario.json" "$NAME" <<'PY'
import json, subprocess, sys
scen = json.load(open(sys.argv[1])); name = sys.argv[2]
def psql(sql):
    r = subprocess.run(["docker","exec","-i","-e","PGOPTIONS=-c client_min_messages=warning",name,"psql","-U","supabase_admin","-h","/var/run/postgresql","-d","postgres","-X","-q","-A","-t","-v","ON_ERROR_STOP=1","-c",sql],capture_output=True,text=True)
    if r.returncode: raise SystemExit("SQL failed: "+r.stderr.strip()[:300])
    return r.stdout.strip()
def lit(v): return "NULL" if v is None else "'" + str(v).replace("'","''") + "'"
# seed: the same rows the model starts with (FK/trigger checks off only while seeding; the account rows are stubs)
seed = scen["seed"]; accts = sorted({p["account_id"] for p in seed["audio_guide_products"]})
sql = ["SET session_replication_role = replica;"]
for a in accts: sql.append(f"INSERT INTO public.accounts (id, name, owner_user_id) VALUES ({lit(a)}, 'stub', gen_random_uuid());")
for p in seed["audio_guide_products"]:
    sql.append(f"INSERT INTO public.audio_guide_products (id, account_id, product_key, display_name, active, revision) VALUES ({lit(p['id'])},{lit(p['account_id'])},{lit(p['product_key'])},{lit(p['display_name'])},{str(p['active']).lower()},{p['revision']});")
for i in seed["audio_guide_items"]:
    sql.append(f"INSERT INTO public.audio_guide_items (id, account_id, product_id, position, voice_sha256, voice_path, bytes, duration_ms, pre_delay_seconds, status) VALUES ({lit(i['id'])},{lit(i['account_id'])},{lit(i['product_id'])},{i['position']},{lit(i['voice_sha256'])},{lit('account-'+i['account_id']+'/'+i['voice_sha256']+'.ogg')},1000,5000,{i['pre_delay_seconds']},{lit(i['status'])});")
psql("\n".join(sql))
kinds = {"p_expected":"integer","p_expected_revision":"integer","p_active":"boolean"}
def typed(k, v):
    t = kinds.get(k) or ("uuid" if k in ("p_account","p_id","p_item","p_purpose","p_identifier","p_contact","p_conversation","p_run") else "text")
    return f"{lit(v)}::{t}"
real = {}; bad = 0
for step in scen["steps"]:
    args = {}
    for k, v in step["args"].items():
        args[k] = real[v["ref"]] if isinstance(v, dict) and "ref" in v else v
    call = f"SELECT public.{step['fn']}(" + ", ".join(f"{k} => {typed(k, v)}" for k, v in args.items()) + ")::text;"
    got = json.loads(psql(call)); want = step["result"]
    for key in ("id", "request_id"):
        if key in got: real[f"{step['label']}.{key}"] = got[key]
    norm = lambda d: {k: ("<id>" if k in ("id", "request_id") else v) for k, v in d.items()}
    same = norm(got) == norm(want)
    print(("PASS " if same else "FAIL ") + f"{step['label']:28s} {step['fn'].replace('audio_guide_','')}: {json.dumps(norm(got), sort_keys=True)}" + ("" if same else f"   MODEL SAID {json.dumps(norm(want), sort_keys=True)}"))
    bad += 0 if same else 1
# the rows the selective request wrote must also agree with the model's expectations (names seen, node key, one send with the audio's own pause)
row = json.loads(psql("SELECT row_to_json(r)::text FROM (SELECT selection_mode, purpose_name, identifier_name, node_key, status, (SELECT count(*) FROM public.audio_guide_sends s WHERE s.request_id = q.id) AS sends, (SELECT pre_delay_seconds FROM public.audio_guide_sends s WHERE s.request_id = q.id) AS pause FROM public.audio_guide_requests q WHERE trigger_message_id = 'wamid.1#vp') r;"))
expect = {"selection_mode":"single","purpose_name":"pago","identifier_name":"Principal","node_key":"vp","status":"claimed","sends":1,"pause":5}
print(("PASS " if row == expect else "FAIL ") + "request row written by open_selected_request: " + json.dumps(row, sort_keys=True)); bad += 0 if row == expect else 1
print(f"---- {len(scen['steps'])+1-bad} PASS, {bad} FAIL")
print("MODEL == SQL" if bad == 0 else "MODEL DIFFERS FROM SQL")
sys.exit(1 if bad else 0)
PY
